from os import path

from ta_tti_collector.utils import LOCAL_MACHINE  # noqa: E402, F401

SP = '/tmp/TtiTraceServer{}/'
CN = 'TTITraceStreamingClient/'
TT_BINS = {'server': 'TTITraceServer.linux', 'client': 'TTITraceStreamingClient.linux'}


def get_tts_path(name, enb):
    # type: (str, str) -> str
    """Returns path to server or client folder."""
    if name == 'server':
        return SP.format(enb)
    elif name == 'client':
        return path.join(SP.format(enb), CN)


def get_tts_bin(name, enb):
    # type: (str, str) -> str
    """Returns path to server or client binary."""
    _path = get_tts_path(name, enb)
    return path.join(_path, TT_BINS[name])
